export const getFashionProducts = (): Product[] => FASHION_PRODUCTS;

export const getFeaturedFashionProducts = (): Product[] => 
  FASHION_PRODUCTS.filter(product => product.featured);

export const getFashionProductsByBadge = (badge: string): Product[] =>
  FASHION_PRODUCTS.filter(product => product.badge === badge);

export const getFashionProductsByPriceRange = (min: number, max: number): Product[] =>
  FASHION_PRODUCTS.filter(product => product.price >= min && product.price <= max);
